-- 0177: ตั้งขนาดรวมคลิปสูงสุดต่อสัญญา = 12 MB
-- apply ผ่าน MCP บน prod แล้วเมื่อ 2026-11-02 ตามที่เจ้าของ (คุณเตย) เคาะ — ไฟล์นี้บันทึกให้ตรงกับที่รันจริง
update app_settings set value = '12', description = 'ขนาดรวมสูงสุดของคลิป 2 คลิป (เทสล็อก + รอบตัวเครื่อง) ต่อ 1 สัญญา หน่วย MB — คุณเตยเคาะ 12 เมื่อ 2026-11-02 (เพดานอีเมลยังเป็น 16 ถ้ารูป+คลิปเกิน ระบบเตือนตอนส่งตรวจ)' where key = 'media_video_total_max_mb';
